if(location.pathname.replace(/\/$/,'')==='/patrocinar'){
if(!document.documentElement.hasAttribute('data-site-rendered'))document.title='Seja nosso patrocinador — Luta pela Comunidade';
if(!document.documentElement.hasAttribute('data-site-rendered')||!document.querySelector('main form'))document.querySelector('main').innerHTML=`<section class="detail-hero registration-intro"><p class="eyebrow">EMPRESAS QUE TRANSFORMAM POSSIBILIDADES</p><h1>Sua empresa pode<br>fazer parte.</h1><p class="lead">Conte como sua empresa deseja apoiar o Luta pela Comunidade. Vamos conversar sobre uma parceria com propósito, acompanhamento e responsabilidades claras.</p></section><section class="section registration-layout"><form id="sponsor-form"><div class="form-status" id="sponsor-status" role="status">Verificando disponibilidade do formulário…</div><p class="field-help">Os campos identificados como opcionais podem ficar em branco.</p><fieldset><legend>01 · Empresa e contato</legend><div class="form-grid"><label class="wide">Nome da empresa<input name="company" autocomplete="organization" required minlength="3" maxlength="150"></label><label>Cidade / UF <small>(opcional)</small><input name="city" maxlength="100" placeholder="Petrópolis / RJ"></label><label>Cargo <small>(opcional)</small><input name="role" autocomplete="organization-title" maxlength="100"></label><label class="wide">Nome completo do contato<input name="contact" autocomplete="name" required minlength="3" maxlength="150"></label><label>E-mail profissional<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label>Telefone / WhatsApp<input name="phone" type="tel" autocomplete="tel" required maxlength="25" pattern="[+0-9 ()-]{10,25}" placeholder="(24) 99999-9999"></label></div></fieldset><fieldset><legend>02 · Como deseja apoiar?</legend><div class="form-grid"><label class="wide">Modalidade de apoio<select name="support" required><option value="">Selecione uma opção</option><option>Patrocínio financeiro</option><option>Materiais e equipamentos</option><option>Alimentação</option><option>Espaços e serviços</option><option>Apoio a um núcleo</option><option>Quero conhecer as possibilidades</option></select></label><label class="wide">Núcleo de interesse<select name="unit" required><option value="">Selecione uma opção</option><option>Projeto como um todo</option><option>Amavale</option><option>Valparaíso</option><option>Vale do Carangola</option><option>A definir</option></select></label><label class="wide">Valor ou recursos estimados <small>(opcional)</small><input name="budget" maxlength="120" placeholder="Ex.: apoio mensal, kimonos ou serviços"></label><label class="wide">Conte sobre o interesse da empresa<textarea name="message" required minlength="10" maxlength="3000" rows="6" placeholder="Descreva o apoio, objetivos, prazo ou dúvidas sobre a parceria."></textarea></label></div><p class="field-help">Até 3.000 caracteres. Não é necessário enviar documentos nesta etapa.</p></fieldset><fieldset class="consents"><legend>03 · Autorização para contato</legend><div class="privacy-note"><p>As informações serão utilizadas pela equipe do Luta pela Comunidade, realizado pela FJJE-Rio, para avaliar a proposta e conversar sobre a parceria.</p><p>O formulário será encaminhado para <strong>patrocinador@lutapelacomunidade.com.br</strong> e <strong>tezzei@gmail.com</strong>. Para solicitar correção ou exclusão, contate patrocinador@lutapelacomunidade.com.br.</p></div><label><input name="consent" type="checkbox" required><span>Autorizo a equipe a usar os dados informados para analisar o interesse em patrocínio e entrar em contato comigo. Estou ciente do envio aos dois e-mails indicados acima.</span></label></fieldset><div class="honeypot" aria-hidden="true"><input name="website" tabindex="-1" autocomplete="off" aria-label="Site pessoal"></div><div id="sponsor-message" role="alert" tabindex="-1"></div><button type="submit" class="button" id="sponsor-submit" disabled>Enviar interesse em patrocinar</button><p class="field-help">Esta manifestação de interesse não formaliza contrato nem compromisso financeiro.</p></form><aside class="registration-aside"><p class="eyebrow">UMA PARCERIA COM PROPÓSITO</p><h2>Mais oportunidades.<br>Juntos.</h2><ul><li>Apoio financeiro e continuidade das atividades.</li><li>Kimonos, uniformes, tatames e equipamentos.</li><li>Alimentação dos participantes.</li><li>Espaços, serviços ou apoio a um núcleo.</li></ul><p>As modalidades e contrapartidas serão conversadas com a coordenação.</p><a class="text-link" href="/#patrocinio">Conhecer nosso patrocinador</a></aside></section>`;
const form=document.querySelector('#sponsor-form'),button=document.querySelector('#sponsor-submit'),status=document.querySelector('#sponsor-status'),message=document.querySelector('#sponsor-message');const initialSubmitLabel=button.textContent;
let enabled=false,id=crypto.randomUUID();
form.addEventListener('input',()=>{id=crypto.randomUUID()});form.addEventListener('change',()=>{id=crypto.randomUUID()});
fetch('/api/sponsorship-status',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject()).then(d=>{enabled=d.enabled===true;button.disabled=!enabled;status.textContent=enabled?'Preencha os dados para apresentar seu interesse em patrocinar.':'O envio pelo formulário ainda não está disponível. Você pode falar com a equipe pelo e-mail patrocinador@lutapelacomunidade.com.br.'}).catch(()=>{status.textContent='O envio pelo formulário ainda não está disponível. Você pode falar com a equipe pelo e-mail patrocinador@lutapelacomunidade.com.br.'});
form.addEventListener('submit',async e=>{e.preventDefault();if(!enabled||!form.reportValidity())return;button.disabled=true;button.textContent='Enviando…';message.textContent='';const data=Object.fromEntries(new FormData(form));data.consent=form.elements.consent.checked;data.requestId=id;try{const r=await fetch('/api/sponsorships',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await r.json();message.textContent=result.message;message.className=r.ok?'form-success':'form-error';if(r.ok){message.textContent+=` Protocolo: ${result.protocol}`;form.reset();id=crypto.randomUUID()}}catch{message.className='form-error';message.textContent='Não foi possível confirmar o envio. Seus campos foram preservados; tente novamente.'}finally{button.disabled=false;button.textContent=initialSubmitLabel;message.focus()}});
}
